void CEngineWaterSettings::CalcReflectToRefractBlendFactors(float start, float end)
{
    float scale = 1.0f / (end - start);
    ReflectToRefractBlendMult = -1.0f * scale;
    ReflectToRefractBlendAdd = 1.0f - start * scale;
}

